<link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Be+Vietnam+Pro:wght@400;500;600;700&family=Dancing+Script:wght@600;700&display=swap" rel="stylesheet">
<style>
.dr-header__utility{border-bottom:1px solid rgba(255,255,255,.12);background:rgba(4,27,25,.76)}
.dr-header__utility-inner{min-height:38px;display:flex;align-items:center;justify-content:space-between;gap:24px}
.dr-header__welcome{color:#cbd9d5;font-size:12px}
.dr-tools{display:flex;align-items:center;gap:14px;min-width:0}
.dr-tool-link{display:inline-flex;align-items:center;gap:7px;color:#f1f5f4;font-size:12px;font-weight:600;transition:color .2s}
.dr-tool-link:hover,.dr-account-link:hover{color:var(--dr-gold)}
.dr-tool-link svg{width:18px;height:18px;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}
.dr-tool-link--cart{position:relative}
.dr-cart-count{display:grid;place-items:center;min-width:18px;height:18px;padding:0 5px;border-radius:10px;background:var(--dr-gold);color:#fff;font-size:10px}
.dr-tools__divider{width:1px;height:16px;background:rgba(255,255,255,.28)}
.dr-account-link{font-size:12px;font-weight:600;white-space:nowrap}
.dr-account-separator{color:rgba(255,255,255,.45)}
:root{--dr-green:#0d3b35;--dr-deep:#071e1c;--dr-gold:#dda149;--dr-red:#e33c3d;--dr-white:#fff;--dr-muted:#c8d2cf;--dr-card:#e9e9e9}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--dr-green);color:#fff;font-family:'Be Vietnam Pro',sans-serif}.dr-page{overflow:hidden}.dr-container{width:min(1180px,calc(100% - 40px));margin:auto}a{color:inherit;text-decoration:none}img{display:block;width:100%;object-fit:cover}.dr-header{position:absolute;z-index:30;top:0;left:0;right:0;background:rgba(8,45,41,.9);border-top:1px solid rgba(221,161,73,.5)}.dr-header__inner{height:82px;display:flex;align-items:center;gap:30px}.dr-brand{display:flex;align-items:center;gap:10px;min-width:190px;color:var(--dr-gold)}.dr-brand img{max-width:180px;max-height:64px;object-fit:contain}.dr-brand__seal{width:52px;height:52px;border-radius:50%;display:grid;place-items:center;border:3px solid #f2c071;background:var(--dr-gold);color:#fff;font-size:24px}.dr-brand strong{font:700 29px/1 'Dancing Script',cursive}.dr-brand small{display:block;font-size:14px}.dr-nav{display:flex;align-items:center;gap:25px;flex:1;justify-content:center}.dr-nav a{font-weight:600;font-size:14px;white-space:nowrap}.dr-nav a:hover{color:var(--dr-gold)}.dr-tools{display:flex;gap:15px;align-items:center}.dr-tools>a:not(.dr-book){font-size:25px}.dr-book,.dr-hero__content a,.dr-contact button{background:var(--dr-gold);padding:14px 22px;border-radius:8px;font-weight:700;color:#fff}.dr-menu-toggle{display:none;background:none;border:0;color:#fff;font-size:26px}.dr-hero{height:720px;position:relative}.dr-hero__slide{position:absolute;inset:0;opacity:0;transition:opacity .7s}.dr-hero__slide.is-active{opacity:1;z-index:1}.dr-hero__slide>img{height:100%}.dr-hero__shade{position:absolute;inset:0;background:linear-gradient(180deg,rgba(3,13,16,.65),rgba(4,20,19,.45) 60%,var(--dr-green))}.dr-hero__content{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;padding-top:60px}.dr-hero__content p,.dr-script,.dr-heading h2{font-family:'Dancing Script',cursive}.dr-hero__content p{font-size:48px;margin:0}.dr-hero__content h1{font-size:25px;letter-spacing:3px;margin:18px 0}.dr-hero__content small{font-size:16px;margin-bottom:30px}.dr-dots{position:absolute;z-index:4;left:50%;bottom:25px;display:flex;gap:8px;transform:translateX(-50%)}.dr-dots button{width:11px;height:11px;border:1px solid var(--dr-gold);background:transparent;border-radius:3px;padding:0}.dr-dots button.is-active{background:var(--dr-gold)}.dr-section{padding:86px 0}.dr-kicker{color:var(--dr-gold);font-style:italic;letter-spacing:2px}.dr-about__grid{display:grid;grid-template-columns:1fr 1.1fr;gap:65px;align-items:center}.dr-script{font-size:52px;margin:12px 0 25px}.dr-about p{line-height:1.9;color:#e4ecea}.dr-link{display:inline-block;color:var(--dr-gold);margin-top:15px}.dr-collage{display:grid;grid-template-columns:1.2fr 1fr;gap:7px}.dr-collage img{height:200px}.dr-collage img:nth-child(1){border-radius:90px 8px 8px 8px}.dr-collage img:nth-child(2){border-radius:8px 90px 8px 8px}.dr-collage img:nth-child(3){border-radius:8px 8px 8px 90px}.dr-collage img:nth-child(4){border-radius:8px 8px 90px 8px}.dr-heading{display:flex;justify-content:center;align-items:center;gap:20px;margin-bottom:48px}.dr-heading h2{font-size:52px;margin:0}.dr-heading span{color:var(--dr-gold);font-size:24px}.dr-category-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:24px}.dr-category-grid article{border:1px solid rgba(255,255,255,.65);padding:28px;text-align:center;border-radius:8px;transition:.25s}.dr-category-grid article:hover{border-color:var(--dr-gold);transform:translateY(-5px)}.dr-category-grid img{width:145px;height:145px;margin:auto}.dr-category-grid h3{font-size:22px}.dr-category-grid p{color:#dbe5e2;line-height:1.7;font-size:14px}.dr-menu{background:#0b342f}.dr-tabs{display:flex;justify-content:center;gap:10px;flex-wrap:wrap;margin:-20px 0 30px}.dr-tabs button{background:transparent;border:1px solid #fff;color:#fff;padding:11px 18px;border-radius:8px;font-weight:700}.dr-tabs button.is-active{background:var(--dr-gold);border-color:var(--dr-gold)}.dr-product-grid{display:grid;grid-template-columns:repeat(5,1fr);gap:22px}.dr-product-card{background:var(--dr-card);color:#111;text-align:center;box-shadow:5px 5px rgba(255,255,255,.45);margin-bottom:24px}.dr-product-card[hidden]{display:none}.dr-product-card__image{position:relative}.dr-product-card__image img{height:220px}.dr-product-card__image>span{position:absolute;right:8px;top:8px;background:var(--dr-red);color:#fff;border-radius:10px;padding:6px 12px;font-weight:700}.dr-product-card__image i{position:absolute;bottom:-27px;left:50%;transform:translateX(-50%);width:62px;height:50px;padding-top:13px;background:var(--dr-gold);color:#fff;border-radius:50px 50px 0 0;font-style:normal;font-size:22px}.dr-product-card h3{font-size:15px;margin:34px 8px 12px;min-height:38px}.dr-product-card p{margin:0 0 20px}.dr-product-card strong{color:var(--dr-red);font-size:18px}.dr-product-card del{color:#888;margin-left:8px;font-size:12px}.dr-product-card>a>b{display:inline-block;background:var(--dr-gold);color:#fff;border-radius:8px;padding:11px 18px;transform:translateY(15px)}.dr-image-strip{display:grid;grid-template-columns:repeat(4,1fr);gap:24px}.dr-image-strip img{height:330px;filter:brightness(.7)}.dr-stats{display:grid;grid-template-columns:repeat(4,1fr);margin-top:18px}.dr-stats article{display:flex;justify-content:center;gap:18px;align-items:center;border-right:1px solid rgba(255,255,255,.35)}.dr-stats article:last-child{border:0}.dr-stats>article>span{font-size:44px;color:var(--dr-gold)}.dr-stats strong{display:block;font-size:40px}.dr-stats small{font-size:16px;letter-spacing:2px}.dr-post-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:28px}.dr-post-grid article{background:#030303;border-radius:8px;overflow:hidden}.dr-post-grid img{height:260px}.dr-post-grid article:nth-child(2){display:flex;flex-direction:column-reverse}.dr-post-grid article>div{padding:28px}.dr-post-grid time{display:inline-block;background:var(--dr-gold);border-radius:8px;padding:8px 13px}.dr-post-grid small{display:block;margin:18px 0}.dr-post-grid h3{font-size:21px;line-height:1.5}.dr-post-grid p{color:#bbb;line-height:1.6}.dr-post-grid a{display:inline-block;color:var(--dr-gold);border-top:1px solid #777;padding-top:18px;width:100%}.dr-testimonials{min-height:440px;padding:72px 0;background:linear-gradient(90deg,#050b0e 20%,rgba(5,11,14,.55)),var(--dr-testimonial-bg) center/cover}.dr-quote{max-width:620px}.dr-quote article{display:none;background:var(--dr-green);padding:38px;border-radius:8px;min-height:240px}.dr-quote article.is-active{display:block}.dr-quote header{display:flex;align-items:center;gap:18px}.dr-quote img{width:70px;height:70px;border-radius:50%}.dr-quote h3{font-size:25px;margin:0}.dr-quote span{color:var(--dr-gold);letter-spacing:2px}.dr-quote b{margin-left:auto;font-size:70px;color:var(--dr-gold)}.dr-quote p{line-height:1.8}.dr-dots--static{position:static;transform:none;margin:22px 0 0;justify-content:center}.dr-contact{background:linear-gradient(135deg,#f1eadc,#fff);color:#152d29}.dr-contact__grid{display:grid;grid-template-columns:.9fr 1.1fr;gap:70px;align-items:center}.dr-contact h2{font-size:42px;line-height:1.25}.dr-contact__info{display:grid;gap:12px;margin-top:25px}.dr-contact__info p{background:#fff;border-left:4px solid var(--dr-gold);padding:14px;margin:0}.dr-contact__info b{display:block;color:var(--dr-green)}.dr-contact form{background:var(--dr-green);padding:32px;border-radius:14px;box-shadow:0 20px 60px rgba(0,0,0,.18)}.dr-contact form>div{display:grid;grid-template-columns:1fr 1fr;gap:15px}.dr-contact label{display:block;color:#fff;font-size:13px;margin-bottom:15px}.dr-contact input,.dr-contact textarea{display:block;width:100%;margin-top:7px;padding:13px;border:1px solid rgba(255,255,255,.25);background:rgba(255,255,255,.08);color:#fff;border-radius:7px;font:inherit}.dr-contact textarea{height:110px;resize:vertical}.dr-contact button{border:0;width:100%;font:700 15px inherit;cursor:pointer}.dr-footer{background:#092e2a;padding:65px 0 0}.dr-footer__grid{display:grid;grid-template-columns:1.5fr .8fr .8fr 1fr;gap:50px}.dr-footer h3{text-transform:uppercase;font-size:15px;margin:0 0 23px}.dr-footer p{color:#d6e2df;line-height:1.7;font-size:14px}.dr-footer section>a{display:block;margin:0 0 17px;color:#d6e2df}.dr-footer__brand{display:flex;gap:12px;align-items:center;color:var(--dr-gold);font:700 27px 'Dancing Script',cursive}.dr-social,.dr-pay{display:flex;gap:10px;flex-wrap:wrap}.dr-social a,.dr-pay span{background:#fff;color:#155047;border-radius:7px;padding:9px;font-size:12px;font-weight:700}.dr-footer__bottom{text-align:center;margin-top:45px;padding:18px;border-top:1px solid rgba(255,255,255,.12);color:#9db4af;font-size:12px}.dr-cms{min-height:65vh;padding-top:150px;background:#fff;color:#222}
@media(max-width:1050px){.dr-nav{position:absolute;top:82px;left:20px;right:20px;display:none;flex-direction:column;background:#092e2a;padding:25px;border-radius:10px}.dr-nav.is-open{display:flex}.dr-menu-toggle{display:block;margin-left:auto}.dr-tools>a:not(.dr-book){display:none}.dr-product-grid{grid-template-columns:repeat(3,1fr)}.dr-category-grid{grid-template-columns:repeat(2,1fr)}}
@media(max-width:720px){.dr-container{width:min(100% - 28px,1180px)}.dr-header__inner{height:70px}.dr-brand{min-width:0}.dr-brand__seal{width:44px;height:44px}.dr-brand strong{font-size:23px}.dr-book{padding:10px 12px;font-size:12px}.dr-hero{height:640px}.dr-hero__content p{font-size:38px}.dr-hero__content h1{font-size:19px}.dr-section{padding:60px 0}.dr-about__grid,.dr-contact__grid{grid-template-columns:1fr}.dr-collage img{height:130px}.dr-heading h2,.dr-script{font-size:38px}.dr-category-grid,.dr-product-grid,.dr-image-strip,.dr-stats,.dr-post-grid,.dr-footer__grid{grid-template-columns:1fr}.dr-product-grid--featured{grid-template-columns:repeat(2,1fr)}.dr-product-card__image img{height:190px}.dr-image-strip{grid-template-columns:repeat(2,1fr)}.dr-image-strip img{height:200px}.dr-stats{grid-template-columns:repeat(2,1fr);gap:25px}.dr-stats article{border:0;justify-content:flex-start}.dr-stats strong{font-size:30px}.dr-post-grid article:nth-child(2){display:block}.dr-contact form>div{grid-template-columns:1fr}.dr-footer__grid{gap:30px}.dr-tools{gap:8px}}
.dr-tools>a.dr-tool-link,.dr-tools>a.dr-account-link{font-size:12px}
@media(max-width:1050px){.dr-nav{top:120px}.dr-tools>a{display:inline-flex!important;font-size:12px}}
@media(max-width:850px){.dr-header__utility-inner{min-height:42px}.dr-header__welcome,.dr-tool-link span,.dr-tools__divider{display:none}.dr-tools{margin-left:auto;gap:11px}.dr-tool-link svg{width:20px;height:20px}.dr-tools>a.dr-account-link{font-size:11px}.dr-nav{top:124px}}
@media(max-width:720px){.dr-header__utility-inner{min-height:42px}.dr-header__welcome,.dr-tool-link span,.dr-tools__divider{display:none}.dr-tools{margin-left:auto;gap:11px}.dr-tools>a{display:inline-flex!important}.dr-tool-link svg{width:20px;height:20px}.dr-account-link{font-size:11px}.dr-nav{top:112px}}
</style>
